cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void matrix_mult_kernel(const float* a, const float* b, float* out, int M, int N, int K) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < M && col < N) {
        float sum = 0.0f;
        for (int k = 0; k < K; k++) {
            sum += a[row * K + k] * b[k * N + col];
        }
        out[row * N + col] = sum;
    }
}

torch::Tensor matrix_mult_cuda(torch::Tensor a, torch::Tensor b) {
    int M = a.size(0);
    int K = a.size(1);
    int N = b.size(1);

