### Iteration 2: Shared Memory Optimization
We'll use shared memory to cache blocks of the input matrices, reducing global memory accesses. This is particularly effective for matrix multiplication since each element is accessed multiple times.

```python
# r02_i02_cuda_kernel.py
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the optimized CUDA kernel with shared memory
cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_SIZE 16

__global__ void matrix_mult_kernel(const float* a, const float* b, float* out, int M, int N, int K) {
    // Shared memory for tiles
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int row = blockIdx.y * blockDim.y + ty;
    int col = blockIdx.x * blockDim.x + tx;

    float sum = 0.0f;

    for (int tile = 0; tile < (K + TILE_SIZE - 1) / TILE_SIZE; tile++) {
        // Load tile from A into shared memory
        int a_col = tile * TILE_SIZE + tx;
        if (row < M && a_col < K) {
            As[ty][tx] = a[row * K + a_col];
        } else {
            As[ty][tx] = 0.0f;
        }

        // Load tile from B into shared memory
        int b_row = tile * TILE_SIZE + ty;
        if (b_row < K && col < N) {
            Bs[ty][tx] = b[b_row * N + col];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial dot product
        for (int k = 0; k < TILE_SIZE; k++) {
            sum += As[ty][k] * Bs[k][tx];
        }

        __syncthreads();
    }

    if (row < M && col < N) {
        out[row * N + col] = sum;
    }
}

