    int M = a.size(0);
    int K = a.size(1);
    int N = b.size(1);

    auto out = torch::empty({M, N}, a.options());

    dim3 threadsPerBlock(TILE_SIZE, TILE_SIZE);
    dim3 numBlocks((N + TILE_SIZE - 1) / TILE_SIZE, 
                   (M + TILE_SIZE - 1) / TILE_SIZE);

    matrix_mult_kernel<<<numBlocks, threadsPerBlock>>>(
        a.data_ptr<float>(), 
        b.data_ptr<float>(), 
        out.data_ptr<float>(), 
        M, N, K
    );

    return out;
}
"""

# Load the CUDA kernel
