#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32

__global__ void matrix_mult_kernel(const float* a, const float* b, float* out, int M, int N, int K) {
    // Shared memory for tiles
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Each thread computes 4 output elements
    int row = blockIdx.y * TILE_SIZE + ty * 2;
    int col = blockIdx.x * TILE_SIZE + tx * 2;

    float sum00 = 0.0f;
    float sum01 = 0.0f;
    float sum10 = 0.0f;
    float sum11 = 0.0f;

    for (int tile = 0; tile < (K + TILE_SIZE - 1) / TILE_SIZE; tile++) {
        // Load tile from A into shared memory
        int a_col = tile * TILE_SIZE + tx * 2;
        if (row < M && a_col < K) {
            As[ty * 2][tx * 2] = a[row * K + a_col];
            As[ty * 2][tx * 2 + 1] = a[row * K + a_col + 1];
        } else {
            As[ty * 2][tx * 2] = 0.0f;
            As[ty * 2][tx * 2 + 1] = 0.0f;
        }
        if (row + 1 < M && a_col < K) {
            As[ty * 2 + 1][tx * 2] = a[(row + 1) * K + a_col];
            As[ty * 2 + 1][tx * 2 + 1] = a[(row + 1) * K + a_col + 1];
        } else {
            As[ty * 2 + 1][tx * 2] = 0.0f;
            As[ty * 2 + 1][tx * 2 + 1] = 0.0f;
        }

        // Load tile from B into shared memory
        int b_row = tile * TILE_SIZE + ty * 2;
        if (b_row < K && col < N) {
            Bs[ty * 2][tx * 2] = b[b_row * N + col];
            Bs[ty * 2][tx * 2 + 1] = b[b_row * N + col + 1];
        } else {
            Bs[ty * 2][tx * 2] = 0.0f;
            Bs[ty * 2][tx * 2 + 1] = 0.0f;
        }
        if (b_row + 1 < K && col < N) {
            Bs[ty * 2 + 1][tx * 2] = b[(b_row + 1) * N + col];
            Bs[ty * 2 + 1][tx * 2 + 1] = b[(b_row + 1) * N + col + 1];
        } else {
            Bs[ty * 2 + 1][tx * 2] = 0.0f;
            Bs[ty * 2 + 1][tx * 2 + 1] = 0.0f;
        }

        __syncthreads();

        // Compute partial dot products
        for (int k = 0; k < TILE_SIZE; k++) {
            float a0 = As[ty * 2][k];
            float a1 = As[ty * 2 + 1][k];
            float b0 = Bs[k][tx * 2];
            float b1 = Bs[k][tx * 2 + 1];

            sum00 += a0 * b0;
            sum01 += a0 * b1;
            sum10 += a1 * b0;
            sum11 += a1 * b1;
        }

        __syncthreads();
